import math

import pytest


def fact(n: int) -> int:
    """Return n! (the product of the integers 1..n); fact(0) == 1.

    Raises ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result


@pytest.mark.parametrize(
    ("n", "expected"),
    [
        (0, 1),
        (1, 1),
        (2, 2),
        (3, 6),
        (5, 120),
        (10, 3628800),
        (20, 2432902008176640000),
    ],
)
def test_fact_known_values(n: int, expected: int) -> None:
    assert fact(n) == expected


def test_fact_matches_math_factorial() -> None:
    for n in range(0, 30):
        assert fact(n) == math.factorial(n)


def test_fact_large_exceeds_64_bit() -> None:
    assert fact(25) == 15511210043330985984000000


def test_fact_recurrence() -> None:
    for n in range(1, 15):
        assert fact(n) == n * fact(n - 1)


@pytest.mark.parametrize("n", [-1, -2, -100])
def test_fact_negative_raises(n: int) -> None:
    with pytest.raises(ValueError):
        fact(n)
